    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
from fractions import Fraction
# Retry until difficulty constraints are met
while True:
    n = rng.randint(7, 10)
    denom_choices = [6, 8, 9, 10, 12, 14, 15]
    triples = []
    denoms_used = []
    # Build n valid triples
    while len(triples) < n:
        d = rng.choice(denom_choices)
        a = rng.randint(0, d - 1)
        b = rng.randint(0, d - 1)
        if a + b > d:
            continue  # ensure r >= 0
        r_num = d - a - b
        P = Fraction(a, d)
        Q = Fraction(b, d)
        R = Fraction(r_num, d)
        # Each is in [0,1], sum to 1 by construction
        triples.append((P, Q, R))
        denoms_used.append(d)
    # Difficulty checks
    unique_triples = set(triples)
    distinct_count = len(unique_triples)
    symmetric_count = sum(1 for P, Q, R in triples if P == Q)
    tie_only_cnt = sum(1 for P, Q, R in triples if R == Fraction(1, 1))
    total_p = sum((P for P, Q, R in triples), Fraction(0, 1))
    total_q = sum((Q for P, Q, R in triples), Fraction(0, 1))
    # Ensure nontrivial, inhomogeneous, and asymmetric setup
    if not (distinct_count >= min(4, n) and symmetric_count <= n // 2 and tie_only_cnt <= 1 and total_p != total_q and len(set(denoms_used)) >= 2):
        continue
    # Build human-readable probability table string
    def frac_to_str(F):
        return f"{F.numerator}/{F.denominator}"
    entries = []
    for i, (P, Q, R) in enumerate(triples, start=1):
        entries.append(f"({frac_to_str(P)}, {frac_to_str(Q)}, {frac_to_str(R)})")
    prob_table_str = "; ".join(entries)
    return {
        'num_matches': n,
        'prob_triples': triples,
        'prob_table_str': prob_table_str
    }

