# Recompute, validate domain constraints, and return (True, answer)
from fractions import Fraction
# Basic structure checks
if 'num_matches' not in assign or 'prob_triples' not in assign:
    # Missing required keys
    return (False, None)
n = assign['num_matches']
triples = assign['prob_triples']
if not isinstance(n, int) or n < 1:
    # Invalid n
    return (False, None)
if not isinstance(triples, list) or len(triples) != n:
    # Triple list must match length
    return (False, None)
# Validate each triple
for t in triples:
    if not (isinstance(t, tuple) and len(t) == 3):
        # Malformed triple
        return (False, None)
    try:
        P, Q, R = Fraction(t[0]), Fraction(t[1]), Fraction(t[2])
    except Exception:
        # Non-fractional entries
        return (False, None)
    if P < 0 or Q < 0 or R < 0:
        # Probabilities must be nonnegative
        return (False, None)
    if P > 1 or Q > 1 or R > 1:
        # Probabilities must be at most 1
        return (False, None)
    if P + Q + R != Fraction(1, 1):
        # Must sum to 1
        return (False, None)
# Enforce difficulty: break symmetry and ensure inhomogeneity
total_p = sum((Fraction(t[0]) for t in triples), Fraction(0, 1))
total_q = sum((Fraction(t[1]) for t in triples), Fraction(0, 1))
if total_p == total_q:
    # Symmetry would trivialize the event by halving
    return (False, None)
if n < 7:
    # Too few matches; not sufficiently challenging
    return (False, None)
distinct_count = len(set(triples))
symmetric_count = sum(1 for P, Q, R in triples if Fraction(P) == Fraction(Q))
tie_only_cnt = sum(1 for P, Q, R in triples if Fraction(R) == Fraction(1, 1))
if distinct_count < min(4, n):
    # Require several distinct triples
    return (False, None)
if symmetric_count > n // 2:
    # Too many symmetric matches reduces difficulty
    return (False, None)
if tie_only_cnt > 1:
    # Avoid degenerate concentration of ties
    return (False, None)
# Require at least two distinct nontrivial denominators across entries
denom_set = set()
for P, Q, R in triples:
    denom_set.add(Fraction(P).denominator)
    denom_set.add(Fraction(Q).denominator)
    denom_set.add(Fraction(R).denominator)
denom_gt1 = {d for d in denom_set if d > 1}
if len(denom_gt1) < 2:
    # All trivial denominators would reduce complexity
    return (False, None)
# Compute the probability via distribution of W-L using dynamic programming
dist = {0: Fraction(1, 1)}  # difference in wins-losses
for P, Q, R in triples:
    P, Q, R = Fraction(P), Fraction(Q), Fraction(R)
    new = {}
    for diff, prob in dist.items():
        new[diff + 1] = new.get(diff + 1, Fraction(0, 1)) + prob * P
        new[diff - 1] = new.get(diff - 1, Fraction(0, 1)) + prob * Q
        new[diff]     = new.get(diff,     Fraction(0, 1)) + prob * R
    dist = new
ans = sum(prob for diff, prob in dist.items() if diff > 0)
# Sanity bounds
if ans <= 0 or ans >= 1:
    # Extremely degenerate instance; reject
    return (False, None)
m = ans.numerator
d = ans.denominator
answer = m + d
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

